--region override
---初始化杂货铺列表数据
function GroceryCatCartNode:InitGroceryData()
    local oriData = GroceryMgr:GetGroceryDataByType(self._curType).products
    local data = {}
    for _, v in ipairs(oriData) do
        if GroceryUtils.CheckItemUnlockShow(v) then
            table.insert(data, v)
        end
    end
    return data
end

---初始化杂货铺类型
function GroceryCatCartNode:InitGroceryType()
    return self._curType
end

-----初始化刷新定时器
function GroceryCatCartNode:InitRefreshTimer()
    local data = GroceryMgr:GetCatCartData()
    if self._curType == GroceryConstants.GroceryType.NightMareQuest then
        data =  GroceryMgr:GetGroceryDataByType(self._curType)
    end
    return data.nextRefreshLeftSeconds
end
--endregion override

