--endregion init

--region handler
--endregion handler

--region public
---刷新页面
---@param groceryType GroceryConstants.GroceryType
function GroceryCatCartNode:Refresh(groceryType)
    self._curType = groceryType
    self:InitData()
    self:InitUI()
    self:RefreshUI()
    self:PlayEnterAnimation()
end

---刷新货币栏
function GroceryCatCartNode:RefreshCurrencyBar()
    local currencyList = GroceryUtils.GetCurrencyByGroceryType(self:GetGroceryType())
    if not currencyList then
        currencyList = {Constants.Currency.FreeDiamondId}
    end
    CfUtils.RefreshTopGoods(currencyList)
end
--endregion public

--region private
---播放进入动画
function GroceryCatCartNode:PlayEnterAnimation()
    self.Root:Stop()
    CfUtils.PlayAnimation(self.Root, "OverseaStoreCoinDialogGo_L")
end
